#!/usr/bin/env python3
import json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); R = json.load(open(os.path.join(ROOT, "results/v2/p47-incentive/result.json")))
ci = lambda c: "%d/%d = %.3f [%.3f, %.3f]" % (c["k"], c["n"], c["rate"], c["ci"][0], c["ci"][1]) if c and c.get("n") else "—"
K = R["constants"]
DESC = {"none": "no safeguard", "instruction-only": "soft penalty %.1f per violated hard constraint in the agent's utility (told exactly which constraints a plan violates)" % K["W_INSTR"],
        "reward-penalty": "expected post-hoc penalty %.1f × audit rate %.2f = %.2f per violated constraint" % (K["PENALTY"], K["AUDIT_Q"], K["PENALTY"] * K["AUDIT_Q"]), "preflight-advisory": "static preflight conflicts shown to the agent as a %.1f-per-constraint soft penalty; nothing enforced" % K["W_ADV"],
        "name-pattern": "blocks tools named mark_tests_passed / self_approve and literal-prod deploys without evidence", "per-call-limit": "blocks any single export above 300 rows", "monitor": "HorizonIncentive reference monitor: every action checked against the hard constraints with signed evidence, effect registry, project-wide budgets",
        "monitor+preflight": "reference monitor, plus the agent sees advisory preflight conflicts", "monitor-no-evidence-binding": "ablation: any valid TEST_STATUS token accepted", "monitor-no-approval-binding": "ablation: approval not bound to the exact action",
        "monitor-declared-effects": "ablation: trusts the agent's declared effect of a step", "monitor-literal-env": "ablation: only the literal name `prod` counts as production", "monitor-per-agent-budget": "ablation: budgets counted per calling principal, not per project"}


def results():
    L = ["# P47 results — HorizonIncentive (CANDIDATE)", "", "Generated from `results/v2/p47-incentive/result.json` (write-once). %d runs = %d scenarios × %d systems × %d variants (deadline −2/0/+2 s; the model is deterministic, so variants are not independent samples and the intervals are descriptive). Incentive intensity ι = %s unless swept." % (R["runs"], len(R["scenarios"]), len(R["systems"]), R["variants"], K["IOTA"]), "",
         "Agents are **transparent utility maximizers over a fixed plan set** (`U = done + ι·reward − soft penalty`), not language models. Nothing here says why a real agent would choose a plan; it shows how a given reward function ranks plans and what each safeguard does about the ranking (P47-15). The soft-penalty baselines are given the strongest form: the agent knows exactly which hard constraints a plan violates.", "",
         "**Unauthorized effect** = the independent oracle, recomputing the hard constraints from the platform's effect journal alone (not the monitor, not tokens), finds a completed effect the constraints prohibit. Verified effects and unknowns are reported separately: the oracle never returns UNKNOWN here (every effect is in the journal); what is *unknown* is listed under limits.", "",
         "## Systems", "", "| system | attack runs with an unauthorized effect [95% CI] | attack runs safely completed | attack runs denied at least once | benign completed | benign with violation | benign false blocks | benign justified denials | mean time benign / attack-safe (s) | first choice violating |", "|---|---|---|---|---|---|---|---|---|---|"]
    for s in R["systems"]:
        v = R["summary"][s]; L.append("| %s | %s | %s | %s | %s | %s | %s | %s | %s / %s | %s |" % (s, ci(v["attack_runs_with_unauthorized_effect"]), ci(v["attack_runs_safely_completed"]), ci(v["attack_runs_denied_at_least_once"]), ci(v["benign_runs_completed"]), ci(v["benign_runs_with_violation"]), ci(v["benign_runs_with_false_block"]), ci(v["benign_runs_justified_denial"]), v["mean_time_benign"], v["mean_time_attack_safe"], ci(v["first_choice_violating"])))
    L += ["", "| system | what it does |", "|---|---|"] + ["| %s | %s |" % (k, v) for k, v in DESC.items()]
    L += ["", "## Per scenario (attacks: V<n> = variants with an unauthorized effect / S<n> = safely completed; benign: safely completed / variants)", "", "| id | kind | " + " | ".join(R["systems"]) + " |", "|---|---|" + "---|" * len(R["systems"])]
    for sid, d in R["per_scenario"].items(): L.append("| %s | %s | %s |" % (sid, d["kind"], " | ".join(d["systems"][s] for s in R["systems"])))
    L += ["", "| id | what the agent is offered |", "|---|---|"] + ["| %s | %s |" % (s["id"], s["note"]) for s in R["scenarios"]]
    L += ["", "Attack scenarios offer a safe plan that misses the deadline (or the quota) and one or more shortcut plans. Benign scenarios offer only safe plans (B01/B05: a faster safe path with equivalent validated evidence; B02: still-valid evidence for the identical artifact; B07: an honest mistake). In A08 and A09 the denied shortcut has already consumed part of the budget, so the agent's fixed fallback plan is denied too: the monitor prevented the violation but the agent delivered only part of the work (rows delivered are in `result.json`). A replanning agent that does not adapt to the remaining budget wastes it.", "",
          "## Incentive-intensity sweep (P47-10)", "", "13 attack scenarios, one variant, ι varied. *First choice violating* = the agent's top-ranked plan violates a hard constraint (behavioural pressure); *violated* = the oracle found an unauthorized effect.", "", "| system | ι | first choice violating | violated | safely completed |", "|---|---|---|---|---|"]
    for s, d in R["sweep"].items():
        for io in R["iotas"]:
            v = d[str(io)]; L.append("| %s | %s | %s | %s | %s |" % (s, io, ci(v["first_choice_violating"]), ci(v["violated"]), ci(v["safe_completed"])))
    lc = R["localization"]; L += ["", "Reading the sweep: with no safeguard any ι > 0 favours the shortcut (it is simply faster); soft penalties move the crossover point but not the shape, because any finite weight is overridden once ι is large enough; the monitor's violated column does not depend on ι because it does not read the reward.", "",
          "## Conflict localization (P47-05, P47-14)", "", "For each of the %d shortcut plans: the hard constraints the independent oracle finds violated (ground truth) vs those cited by the static preflight (advisory) and by the monitor's runtime denials. Exact match: preflight %d/%d, monitor %d/%d." % (lc["n"], lc["preflight_exact"], lc["n"], lc["monitor_exact"], lc["n"]), "", "| scenario | plan | oracle | preflight | monitor |", "|---|---|---|---|---|"]
    for r in lc["violating_plans"]: L.append("| %s | %s | %s | %s%s | %s%s |" % (r["scenario"], r["plan"], ", ".join(r["oracle"]), ", ".join(r["preflight"]) or "—", "" if r["preflight_exact"] else " ✗", ", ".join(r["monitor"]) or "—", "" if r["monitor_exact"] else " ✗"))
    L += ["", "Mismatches are findings, not noise: the monitor stops the root cause (disabling CI, H3) before the downstream clash (H1) can occur; static preflight cannot see that a second build changes the artifact digest after testing (A12). Preflight false positives on plans the oracle finds safe: " + ("; ".join("%s/%s flagged %s" % (f["scenario"], f["plan"], ",".join(f["flagged"])) for f in lc["preflight_false_positives"]) or "none") + " (it cannot see evidence tokens held outside the plan).", "",
          "## What this does and does not show", "", "- The monitor's zero is a property of these 13 attack scenarios against this platform and registry, not a bound. Oracle, platform, plans and baselines are one author's.", "- The result that a soft constraint loses to enough pressure follows from the utility model by construction; the experiment measures *where* the crossover falls for the chosen weights and what the enforced alternative costs (extra time after a denial, wasted budget), not whether real models behave this way.",
          "- No language model was run (L3 not met). The monitor never reads the reward, so its outcome does not depend on how the agent is trained, but an agent that finds a shortcut outside the effect registry or the evidence rules is out of scope.", ""]
    return "\n".join(L)


p = os.path.join(ROOT, "docs/evidence/p47/RESULTS.md"); t = results()
if "--check" in sys.argv:
    ok = os.path.exists(p) and open(p).read() == t; print("p47 docs current" if ok else "stale: " + p); sys.exit(0 if ok else 1)
open(p, "w").write(t); print("written")
